# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">FATIR SURESİ 27-28. AYETLERDE KÂİNATTAKİ ÇEŞİTLİLİK DELİLLERİ</text>\n  <!-- 3 Kutu -->\n  <rect x="25" y="48" width="205" height="190" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="127" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#065f46">1. Bitkiler ve Meyveler</text>\n  <text x="127" y="96" text-anchor="middle" font-size="12" fill="#047857">Gökten indirilen aynı su ile</text>\n  <text x="127" y="114" text-anchor="middle" font-size="12" font-weight="bold" fill="#065f46">renkleri, tatları ve kokuları</text>\n  <text x="127" y="132" text-anchor="middle" font-size="12" fill="#047857">birbirinden farklı meyvelerin</text>\n  <text x="127" y="150" text-anchor="middle" font-size="12" fill="#047857">ve ürünlerin çıkarılması</text>\n  <rect x="40" y="172" width="175" height="48" rx="6" fill="#d1fae5"/>\n  <text x="127" y="193" text-anchor="middle" font-size="11" font-weight="bold" fill="#065f46">İlgili Bilim Dalları:</text>\n  <text x="127" y="210" text-anchor="middle" font-size="11" fill="#047857">Botanik, Ziraat, Meteoroloji</text>\n\n  <rect x="247" y="48" width="205" height="190" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">2. Dağlar ve Kayaçlar</text>\n  <text x="350" y="96" text-anchor="middle" font-size="12" fill="#78350f">Dağlarda tonları farklı</text>\n  <text x="350" y="114" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">beyaz, kırmızı ve simsiyah</text>\n  <text x="350" y="132" text-anchor="middle" font-size="12" fill="#78350f">(garâbîbü sûd) yolların ve</text>\n  <text x="350" y="150" text-anchor="middle" font-size="12" fill="#78350f">kayaç katmanlarının varlığı</text>\n  <rect x="262" y="172" width="175" height="48" rx="6" fill="#fde68a"/>\n  <text x="350" y="193" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">İlgili Bilim Dalları:</text>\n  <text x="350" y="210" text-anchor="middle" font-size="11" fill="#78350f">Jeoloji, Coğrafya, Mineraloji</text>\n\n  <rect x="470" y="48" width="205" height="190" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="572" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">3. İnsanlar ve Canlılar</text>\n  <text x="572" y="96" text-anchor="middle" font-size="12" fill="#1e3a8a">İnsanların, hayvanların (devâbb)</text>\n  <text x="572" y="114" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">ve sağmal hayvanların (en\'âm)</text>\n  <text x="572" y="132" text-anchor="middle" font-size="12" fill="#1e3a8a">farklı renk, ırk, dil ve</text>\n  <text x="572" y="150" text-anchor="middle" font-size="12" fill="#1e3a8a">özelliklerde yaratılması</text>\n  <rect x="485" y="172" width="175" height="48" rx="6" fill="#dbeafe"/>\n  <text x="572" y="193" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">İlgili Bilim Dalları:</text>\n  <text x="572" y="210" text-anchor="middle" font-size="11" fill="#1e3a8a">Biyoloji, Zooloji, Antropoloji</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İLİM - TEFEKKÜR - HAŞYET İLİŞKİSİ (FATIR SURESİ 28. AYET)</text>\n  <!-- Akis -->\n  <rect x="35" y="55" width="175" height="115" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="122" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">GÖZLEM VE İLİM</text>\n  <text x="122" y="102" text-anchor="middle" font-size="11" fill="#1e3a8a">Tabiat olaylarını, canlıları</text>\n  <text x="122" y="120" text-anchor="middle" font-size="11" fill="#1e3a8a">ve evrendeki yasaları</text>\n  <text x="122" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">(Sünnetullah) incelemek</text>\n\n  <line x1="210" y1="112" x2="252" y2="112" stroke="#475569" stroke-width="2.5"/>\n  <polygon points="252,107 264,112 252,117" fill="#475569"/>\n\n  <rect x="264" y="55" width="175" height="115" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="351" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">TEFEKKÜR VE İDRAK</text>\n  <text x="351" y="102" text-anchor="middle" font-size="11" fill="#78350f">Sanattan Sanatkâra,</text>\n  <text x="351" y="120" text-anchor="middle" font-size="11" fill="#78350f">eserden Müessire ulaşarak</text>\n  <text x="351" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Allah\'ın kudretini kavramak</text>\n\n  <line x1="439" y1="112" x2="481" y2="112" stroke="#475569" stroke-width="2.5"/>\n  <polygon points="481,107 493,112 481,117" fill="#475569"/>\n\n  <rect x="493" y="55" width="175" height="115" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="580" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">HAŞYET BİLİNCİ</text>\n  <text x="580" y="102" text-anchor="middle" font-size="11" fill="#14532d">Sevgi, tazim ve derin</text>\n  <text x="580" y="120" text-anchor="middle" font-size="11" fill="#14532d">saygıyla karışık sakınma;</text>\n  <text x="580" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">gerçek âlimlerin niteliği</text>\n\n  <!-- Alt Ayet Vurgusu -->\n  <rect x="35" y="185" width="633" height="58" rx="8" fill="#f1f5f9" stroke="#64748b" stroke-width="1.5"/>\n  <text x="350" y="207" text-anchor="middle" font-size="13" font-weight="bold" fill="#0f172a">"Kulları içinden ancak âlimler, Allah\'tan (gereğince) korkar (haşyet duyar)." (Fatır, 28)</text>\n  <text x="350" y="228" text-anchor="middle" font-size="12" fill="#334155">Ayetin Sonu: Şüphesiz Allah Azîz\'dir (mutlak güç sahibidir), Gafûr\'dur (çok bağışlayıcıdır).</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAM MEDENİYETİNDE ÖNE ÇIKAN BİLİM KURUMLARI VE ÂLİMLER</text>\n  <!-- Kurumlar -->\n  <rect x="25" y="45" width="315" height="198" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">TEMEL EĞİTİM VE BİLİM KURUMLARI</text>\n  <text x="40" y="94" font-size="12" fill="#581c87">• Suffe: Mescid-i Nebi\'deki ilk eğitim kurumu.</text>\n  <text x="40" y="116" font-size="12" fill="#581c87">• Beytülhikme: Bağdat\'ta kurulan tercüme ve</text>\n  <text x="50" y="133" font-size="12" fill="#581c87">bilimsel araştırma akademisi (Me\'mun dönemi).</text>\n  <text x="40" y="155" font-size="12" fill="#581c87">• Nizamiye Medresesi: Yükseköğretim kurumu.</text>\n  <text x="40" y="177" font-size="12" fill="#581c87">• Darüşşifa / Bimaristan: Tıp eğitimi ve hastane.</text>\n  <text x="40" y="199" font-size="12" fill="#581c87">• Rasathane: Astronomi gözlemevi (Semerkant, Meraga).</text>\n  <text x="40" y="221" font-size="12" fill="#581c87">• Darülkurra &amp; Darülhadis: İhtisas medreseleri.</text>\n  <!-- Alimler -->\n  <rect x="360" y="45" width="315" height="198" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#9a3412">ÖNCÜ MÜSLÜMAN BİLİM İNSANLARI</text>\n  <text x="375" y="94" font-size="12" fill="#7c2d12">• Hârizmî: Cebirin kurucusu (Kitâbü\'l-Cebr), sıfır.</text>\n  <text x="375" y="116" font-size="12" fill="#7c2d12">• İbn Sînâ: El-Kânûn fi\'t-Tıb (Tıp ve Felsefe).</text>\n  <text x="375" y="138" font-size="12" fill="#7c2d12">• İbnü\'l-Heysem: Optik biliminin öncüsü (Kitâbü\'l-Menâzır).</text>\n  <text x="375" y="160" font-size="12" fill="#7c2d12">• Cezerî: Sibernetik ve robotik ( mekanik düzenekler).</text>\n  <text x="375" y="182" font-size="12" fill="#7c2d12">• Bîrûnî: Astronomi, coğrafya ve karşılaştırmalı dinler.</text>\n  <text x="375" y="204" font-size="12" fill="#7c2d12">• Pîrî Reis: Kitâb-ı Bahriye ve Dünya Haritası.</text>\n  <text x="375" y="226" font-size="12" fill="#7c2d12">• Uluğ Bey &amp; Ali Kuşçu: Zîc-i Uluğ Bey (Astronomi).</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
